<script setup>
import {ref,onMounted} from 'vue'
import {request} from '../api'
const data=ref(null),error=ref(''),busy=ref(false),handle=ref(''),point=ref({title:'',problem_key:'',criterion:''}),checkin=ref({point_id:'',minutes:45,reflection:''})
const emit=defineEmits(['plan'])
async function load(){data.value=await request('identity','/learning/overview');handle.value=data.value.binding[0]?.HANDLE||''}
async function run(fn){busy.value=true;error.value='';try{await fn();await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>run(async()=>{}))
</script>
<template><section><div class="section-head"><h2>每日学习与结算</h2><button :disabled="busy" @click="run(load)">刷新</button></div><p v-if="error" class="error" role="alert">{{error}}</p><p class="note">{{data?.today}} · 上海时间 · 累计学习积分 {{data?.total_score||0}}。每天打卡 1 分；同一道题首次验证 AC 额外 2 分。结算后记录锁定；未找到 AC 可领取打卡分，之后不能补领该日奖励。OJ 通过是提交证据，知识理解需要另行检查。</p><p v-if="!data&&!error" class="note">正在读取学习记录…</p><div v-if="data" class="settings-grid"><form class="card" @submit.prevent="run(()=>request('identity','/learning/oj-binding','PUT',{provider:'Codeforces',handle}))"><h3>绑定 OJ</h3><p v-if="data.binding.length">已绑定：{{data.binding[0].HANDLE}}</p><label>Codeforces 用户名<input v-model="handle" required pattern="[a-zA-Z0-9_.-]{3,24}"></label><p>读取官方公开提交记录。绑定是用户名关联，尚不证明账号所有权。</p><button :disabled="busy">保存绑定</button></form><form class="card" @submit.prevent="run(()=>request('identity','/learning/points','POST',point))"><h3>添加学习点</h3><label>知识点目标<input v-model="point.title" maxlength="100" required placeholder="例如：二分查找不变量"></label><label>Codeforces 题号<input v-model="point.problem_key" required pattern="[0-9]{1,7}[A-Z][0-9]?" placeholder="例如：4A"></label><label>理解检查标准<textarea v-model="point.criterion" maxlength="500" required placeholder="用自己的话解释复杂度并列出边界测试"></textarea></label><button :disabled="busy">保存学习点</button></form><form class="card" @submit.prevent="run(()=>request('identity','/learning/checkins','POST',checkin))"><h3>今日打卡</h3><label>学习点<select v-model="checkin.point_id" required><option value="">请选择</option><option v-for="p in data?.points||[]" :key="p.ID" :value="p.ID">{{p.TITLE}} · {{p.PROBLEM_KEY}}</option></select></label><label>实际学习分钟<input v-model.number="checkin.minutes" type="number" min="1" max="1440" required></label><label>复盘与困难<textarea v-model="checkin.reflection" maxlength="2000" required></textarea></label><button :disabled="busy">提交今日打卡</button></form></div><h3>已保存的学习目标</h3><article v-for="p in data?.plans||[]" :key="p.LEARNING_DAY" class="card"><strong>{{p.LEARNING_DAY}}</strong><p style="white-space:pre-wrap">{{p.BODY}}</p></article><h3>打卡记录</h3><p v-if="data&&!data.checkins.length" class="empty">还没有打卡。先绑定 Codeforces，添加学习点，再提交今日复盘。</p><article v-for="c in data?.checkins||[]" :key="c.ID" class="card"><strong>{{c.LEARNING_DAY}} · {{c.TITLE}}</strong><p>{{c.REFLECTION}}</p><small>{{c.MINUTES}} 分钟 · {{c.PROBLEM_KEY}} · {{({PENDING:'待验证',NO_MATCH:'未找到当日 AC',VERIFIED:'OJ 已验证 AC'})[c.VERIFICATION]}} · {{c.SETTLED?'已结算 '+c.SCORE+' 分':'未结算'}}</small><p v-if="c.EVIDENCE_HANDLE">验证账号：{{c.EVIDENCE_HANDLE}}</p><p>理解检查：{{c.CRITERION}}</p><a v-if="c.EVIDENCE_ID" :href="'https://codeforces.com/contest/'+c.PROBLEM_KEY.match(/^\d+/)[0]+'/submission/'+c.EVIDENCE_ID" target="_blank" rel="noopener">查看提交证据</a><template v-if="!c.SETTLED"><button :disabled="busy" @click="run(()=>request('identity',`/learning/checkins/${c.ID}/verify`,'POST'))">读取 OJ 验证</button><button :disabled="busy||c.VERIFICATION==='PENDING'" class="secondary" @click="run(()=>request('identity',`/learning/checkins/${c.ID}/settle`,'POST'))">结算本日</button></template></article><button @click="emit('plan')">根据打卡规划明日目标</button></section></template>
